bash -lc 'python3 - <<"PYPATCH"
import io,sys
p = "/src/libxml2/parserInternals.c"
with open(p, "r", encoding="utf-8") as f:
    s = f.read()
start_pat = "if (len + 5 >= size) {"
pos = s.find(start_pat)
if pos == -1:
    print("START BLOCK NOT FOUND", file=sys.stderr)
    sys.exit(1)
# find end of this block by locating the line after the closing brace before COPY_BUF line
end_pat = "COPY_BUF(ql,buf,len,q);"
pos_end = s.find(end_pat, pos)
if pos_end == -1:
    print("END BLOCK NOT FOUND", file=sys.stderr)
    sys.exit(1)
end_brace_pos = s.find("}", pos)
# We want to replace from pos to end_brace_pos inclusive with new block, but the exact end brace may be followed by newline.
new_block = '''size_t need = len + ql + 1;
    if (need >= size) {
        xmlChar *new_buf;
        size_t new_size = size;
        while (need >= new_size)
            new_size *= 2;
        new_buf = (xmlChar *) xmlRealloc(buf, new_size);
        if (new_buf == NULL) {
            xmlFree (buf);
            xmlErrMemory(ctxt, NULL);
            return;
        }
        buf = new_buf;
        size = new_size;
    }
    '''
# Note: we will keep the following line exactly as COPY_BUF(ql,buf,len,q);
replacement = new_block + "COPY_BUF(ql,buf,len,q);"
s2 = s[:pos] + replacement + s[end_brace_pos+1:]
with open(p, 'w', encoding='utf-8') as f:
    f.write(s2)
print("Patched")
PYPATCH'

bash -lc 'ed -s /src/libxml2/parserInternals.c <<"ED"
/if (len + 5 >= size) {
+1a
        /* Robust growth: ensure there is space for upcoming COPY_BUF */
        while (len + 5 >= size) {
            size *= 2;
            xmlChar *new_buf = (xmlChar *) xmlRealloc(buf, size);
            if (new_buf == NULL) {
                xmlFree(buf);
                xmlErrMemory(ctxt, NULL);
                return;
            }
            buf = new_buf;
        }
.
wq
ED'

